import { mock } from 'bun:test';
import assert from 'node:assert/strict';
import React, { act, forwardRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { JSDOM } from 'jsdom';
import { mergeCustomization } from '../../src/lib/customization';

const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', { url: 'https://tatakai.test/' });
for (const name of ['window', 'document', 'navigator', 'HTMLElement', 'Element', 'Node', 'Event', 'MouseEvent', 'MutationObserver', 'getComputedStyle']) Object.defineProperty(globalThis, name, { configurable: true, value: name === 'getComputedStyle' ? dom.window.getComputedStyle.bind(dom.window) : (dom.window as any)[name] });
Object.assign(globalThis, { IS_REACT_ACT_ENVIRONMENT: true, requestAnimationFrame: (callback: any) => setTimeout(callback, 0), cancelAnimationFrame: clearTimeout });
let settings: any = { version: 1, themes: { 'cherry-blossom': { targets: { desktop: { activeDesign: 'old', designs: { old: { id: 'old', name: 'Original custom card', base: 'overlay' } }, pages: { 'anime-home': { order: ['spotlight', 'trending'] } } }, mobile: { activeDesign: 'phone', designs: { phone: { id: 'phone', name: 'Phone', base: 'poster' } } } } }, midnight: { logo: 'dark' } } };
let selection: any = { mode: 'manual', theme: 'cherry-blossom', lightTheme: 'light-minimal', darkTheme: 'cherry-blossom' };
const writes: any[] = [], themeWrites: any[] = [];
let cleanupCount = 0;
mock.module('../../src/hooks/ui/useCustomization', () => ({ useCustomization: () => ({ settings, userId: null, syncStatus: 'saved', savePatch: async (patch: any) => { writes.push(patch); settings = mergeCustomization(settings, patch); } }), useCustomizationScope: () => ({ themeId: 'cherry-blossom', target: 'desktop' }), CustomizationScopeProvider: ({ children }: any) => <>{children}</> }));
mock.module('../../src/hooks/ui/useTheme', () => ({ resolveColors: (id: string) => ({ primary: '340 82% 65%', background: id === 'light-minimal' ? '0 0% 100%' : '240 10% 4%', foreground: '0 0% 98%', isLight: id === 'light-minimal' }), useTheme: () => ({ theme: 'cherry-blossom', selection, setSelection: (next: any) => { themeWrites.push(next); selection = next; }, themes: ['cherry-blossom', 'midnight', 'light-minimal'], themeInfo: { 'cherry-blossom': { name: 'Cherry Blossom' }, midnight: { name: 'Midnight' }, 'light-minimal': { name: 'Light Minimal' } } }) }));
mock.module('react-i18next', () => ({ useTranslation: () => ({ t: (key: string, options?: any) => options?.defaultValue || key }) }));
mock.module('react-router-dom', () => ({ useNavigate: () => () => {} }));
mock.module('sonner', () => ({ toast: { error(message: string) { throw Error(message); } } }));
mock.module('../../src/contexts/SettingsModalContext', () => ({ useSettingsModal: () => ({ closeSettings() {} }) }));
mock.module('../../src/components/ui/button', () => ({ Button: forwardRef<any, any>(({ variant, size, children, ...props }, ref) => <button ref={ref} {...props}>{children}</button>) }));
mock.module('../../src/components/ui/themed-select', () => ({ ThemedSelect: forwardRef<any, any>((props, ref) => <select {...props} ref={ref} />) }));
mock.module('../../src/components/ui/themed-checkbox', () => ({ ThemedCheckbox: (props: any) => <input type="checkbox" {...props} /> }));
mock.module('../../src/components/settings/SettingsPrimitives', () => ({ SettingsSection: ({ title, description, children }: any) => <section><h2>{title}</h2>{description && <p>{description}</p>}{children}</section> }));
mock.module('../../src/components/settings/ThemeSelector', () => ({ ThemeSelector: ({ onSelectTheme }: any) => <button onClick={() => onSelectTheme('midnight')}>Select Midnight</button> }));
mock.module('../../src/components/settings/MediaCardStyleSelector', () => ({ MediaCardStyleSelector: () => <div>Default card styles</div> }));
mock.module('../../src/components/settings/MobileAppearanceSelector', () => ({ MobileAppearanceSelector: () => <div>Mobile appearance</div> }));
mock.module('../../src/components/settings/SpotlightCustomizationEditor', () => ({ SpotlightCustomizationEditor: ({ onChange }: any) => <button onClick={() => onChange({ variant: 'cinematic', height: 480 })}>Apply cinematic spotlight</button> }));
mock.module('../../src/components/branding/BrandLogo', () => ({ BrandLogo: ({ choice }: any) => <img alt="" data-choice={choice} /> }));
mock.module('../../src/components/settings/LauncherIconSelector', () => ({ LauncherIconSelector: () => <div>Launcher settings</div> }));
mock.module('../../src/components/UnifiedMediaCard', () => ({ UnifiedMediaCard: () => <div>Card preview</div> }));
mock.module('../../src/components/tv/TVContentCard', () => ({ TVContentCard: () => <div>TV preview</div> }));
mock.module('../../src/components/settings/BackgroundEditor', () => ({ BackgroundEditor: () => <div>Background editor</div>, AppearanceBackground: () => <div />, AppearanceDraftProvider: ({ children, resetKey }: any) => { useEffect(() => () => { cleanupCount++; }, [resetKey]); return children; } }));

const { CustomizationEditor } = await import('../../src/components/settings/CustomizationEditor');
const root = createRoot(document.getElementById('root')!);
await act(async () => { root.render(<CustomizationEditor />); });
const button = (text: string) => [...document.querySelectorAll('button')].find(node => node.textContent === text)!;
const click = async (text: string) => { const node = button(text); assert(node, `Missing button ${text}`); assert(!node.disabled, `Disabled button ${text}`); await act(async () => { node.dispatchEvent(new MouseEvent('click', { bubbles: true })); }); };
const select = async (text: string, value: string) => {
  const label = [...document.querySelectorAll('label')].find(node => node.querySelector('span')?.textContent === text);
  const element = label?.querySelector('select') as HTMLSelectElement;
  assert(element, `Missing select ${text}`);
  await act(async () => { element.value = value; element.dispatchEvent(new Event('change', { bubbles: true })); });
};
await click('customization.tabs.theme');
await click('customization.logos.legacy');
assert.equal(settings.themes['cherry-blossom'].logo, undefined);
assert.equal(writes.length, 0); assert.equal(themeWrites.length, 0);
await click('customization.cancel');
assert.equal(writes.length, 0); assert(cleanupCount > 0);
assert(button('customization.logos.auto').getAttribute('aria-pressed') === 'true');
await click('customization.logos.monochrome');
await click('customization.save');
assert.deepEqual(writes.at(-1), { themes: { 'cherry-blossom': { logo: 'monochrome' } } });
assert.equal(settings.themes['cherry-blossom'].targets.mobile.activeDesign, 'phone');
assert.deepEqual(settings.themes['cherry-blossom'].targets.desktop.pages['anime-home'].order, ['spotlight', 'trending']);
assert.equal(themeWrites.length, 0);
await click('customization.tabs.cards');
await click('customization.create');
assert.equal(Object.keys(settings.themes['cherry-blossom'].targets.desktop.designs).length, 1);
await select('customization.position', 'top-center');
await click('customization.duplicate');
await click('customization.save');
assert.equal(Object.values(settings.themes['cherry-blossom'].targets.desktop.designs).filter(Boolean).length, 3);
assert.equal(Object.values(settings.themes['cherry-blossom'].targets.desktop.designs).filter((design: any) => design?.slots?.title?.zone === 'top-center').length, 2);
await click('customization.tabs.theme');
await select('customization.mode', 'system');
await click('customization.cancel');
assert.equal(themeWrites.length, 0);
await select('customization.mode', 'system');
await click('customization.save');
assert.equal(themeWrites.at(-1).mode, 'system');
await select('customization.previewTarget', 'tv');
await select('customization.mode', 'system');
await click('customization.save');
assert.equal(settings.tvSelection.mode, 'system');
assert.equal(themeWrites.length, 1);
await click('customization.resetTheme');
assert(settings.themes['cherry-blossom']);
await click('customization.cancel');
assert(settings.themes['cherry-blossom']);
await click('customization.resetTheme');
await click('customization.save');
assert.equal(settings.themes['cherry-blossom'], null);
assert.equal(settings.themes.midnight.logo, 'dark');
const beforeCreate = writes.length;
await click('customization.createTheme');
await select('customization.baseTheme', 'light-minimal');
await click('customization.create');
assert.equal(writes.length, beforeCreate);
assert.equal(settings.customThemes, undefined);
await click('customization.cancel');
assert.equal(settings.customThemes, undefined);
await click('customization.createTheme');
await select('customization.baseTheme', 'light-minimal');
await click('customization.create');
await click('customization.save');
const newThemeId = Object.keys(settings.customThemes)[0];
assert.equal(settings.customThemes[newThemeId].baseTheme, 'light-minimal');
assert.equal(settings.tvSelection.theme, newThemeId);
assert.equal(themeWrites.length, 1);
await click('customization.deleteTheme');
assert(settings.customThemes[newThemeId]);
await click('customization.save');
assert.equal(settings.customThemes[newThemeId], null);
assert.equal(settings.tvSelection.theme, 'cherry-blossom');
await click('customization.tabs.spotlight');
const beforeSpotlight = writes.length;
await click('Apply cinematic spotlight');
assert.equal(writes.length, beforeSpotlight);
await click('customization.save');
assert.equal(settings.themes['cherry-blossom'].targets.tv.spotlight.variant, 'cinematic');
assert.equal(settings.themes['cherry-blossom'].targets.tv.spotlight.height, 480);
assert.equal(themeWrites.length, 1);
await act(async () => { root.unmount(); });
dom.window.close();
console.log('CUSTOMIZATION_EDITOR_SAVE_CANCEL_RESET_OK');
